INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (19, 2, 'theory', 'Quiz: packages and updates');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (19, 2, 0, 'Which version is newer by Debian rules: 1.0~rc1 or 1.0?', '["1.0~rc1, because the string is longer", "They are equal", "1.0, because the tilde sorts before even the end of the string", "They cannot be compared without an epoch"]', 2, 'The tilde marks a pre-release: a part with a tilde is less than an empty part. A missing epoch equals zero, so the comparison is possible.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (19, 2, 1, 'What does the Signed-By field do in a Debian repository description?', '["It ties the repository to a specific key, other keys do not apply to it", "It switches on signature checks for all repositories at once", "It names the author of the packages", "It switches off the signature check for this source"]', 0, 'This way the key is not a trust anchor for the whole system as with the old apt-key: it applies only to its own source.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (19, 2, 2, 'What is true about kernels in dnf by default?', '["One kernel is kept, the others are removed at once", "Two kernels are kept, the running one may be removed", "The number of kernels is unlimited", "Up to three kernels are kept, the running kernel is protected from removal"]', 3, 'The installonly_limit parameter defaults to three, and protect_running_kernel is on. The value 1 is not allowed precisely because of that protection.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (19, 2, 3, 'What does dnf history rollback N do?', '["Cancels only the transaction number N", "Cancels all transactions after N, and if even one cannot be undone, undoes none", "Reinstalls all packages to the distribution state", "Restores configuration files from a backup"]', 1, 'Rollback returns the system to the state after N; undo is for a single transaction. If the database has changed so that an undo is impossible, nothing is rolled back.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (19, 2, 4, 'A third-party repository answers with NO_PUBKEY. What is right?', '["Install the packages with a flag that allows unsigned ones", "Switch off signature checking in the configuration", "Get the key from the owner over a verified channel and name it in Signed-By", "Wait an hour: the error goes away by itself"]', 2, 'The signature is the only link between a package and its author. Disabling the check makes a package substitution possible, and it would run with root rights.');
